// Convierte el mensaje o el botón de Telegram en una acción y arma su SQL
const lit = (v) => (v === null || v === undefined) ? 'null' : "'" + String(v).replace(/'/g, "''") + "'";
const u = $input.first().json;
const out = { tipo: 'otro', chatId: '', id: '', nombre: '', sql: '' };
if (u.callback_query) {
  const q = u.callback_query;
  const [accion, idCita, fecha, hora] = String(q.data || '').split('|');
  Object.assign(out, { chatId: String(q.message.chat.id), queryId: q.id, id: idCita || '', nombre: q.from.first_name || '' });
  out.tipo = { c: 'confirmar', x: 'cancelar', m: 'cambiar', h: 'elegir' }[accion] || 'otro';
  if (out.tipo === 'elegir') {
    out.fecha = fecha.slice(0, 4) + '-' + fecha.slice(4, 6) + '-' + fecha.slice(6, 8);
    out.hora = hora.slice(0, 2) + ':' + hora.slice(2, 4);
  }
} else if (u.message) {
  out.chatId = String(u.message.chat.id);
  out.nombre = u.message.from.first_name || '';
  const m = String(u.message.text || '').match(/^\/start\s+(\S+)/);
  if (m) { out.tipo = 'inicio'; out.id = m[1]; }
}
if (!/^[A-Za-z0-9-]{4,20}$/.test(out.id)) out.tipo = 'otro';
if (out.tipo === 'elegir' && !(/^\d{4}-\d{2}-\d{2}$/.test(out.fecha) && /^\d{2}:\d{2}$/.test(out.hora))) out.tipo = 'otro';
const ID = lit(out.id);
const CHAT = lit(out.chatId);
// Solo el chat conectado a la cita puede tocarla
const suya = 'id = ' + ID + ' and telegram_chat = ' + CHAT + " and estado <> 'Cancelada'";
const SQL = {
  inicio: 'update citas set telegram_chat = ' + CHAT + ' where id = ' + ID + " and estado <> 'Cancelada' returning id, nombre, servicio_nombre, profesional, duracion_min, to_char(fecha, 'YYYY-MM-DD') as fecha, to_char(hora, 'HH24:MI') as hora;",
  confirmar: "update citas set estado = 'Confirmada por paciente' where " + suya + ' returning id;',
  cancelar: "update citas set estado = 'Cancelada' where " + suya + ' returning id;',
  cambiar: `select
  (select row_to_json(h) from horario h where id = 1) as horario,
  coalesce((select json_agg(to_char(fecha, 'YYYY-MM-DD')) from no_atiende where fecha >= current_date), '[]'::json) as no_atiende,
  coalesce((select json_agg(json_build_object('id', id, 'fecha', to_char(fecha, 'YYYY-MM-DD'), 'hora', to_char(hora, 'HH24:MI'), 'dur', duracion_min))
            from citas where estado <> 'Cancelada' and fecha >= current_date), '[]'::json) as citas,
  (select row_to_json(c) from (select id, cambios, duracion_min from citas where ${suya}) c) as cita;`,
  elegir: `update citas c set fecha = ${lit(out.fecha)}::date, hora = ${lit(out.hora)}::time, cambios = c.cambios + 1, estado = 'Reprogramada', recordatorio_enviado = null
where c.id = ${ID} and c.telegram_chat = ${CHAT} and c.estado <> 'Cancelada' and c.cambios < 1
  and ${lit(out.fecha)}::date > (now() at time zone 'America/Bogota')::date
  and not exists (
    select 1 from citas o
    where o.id <> c.id and o.estado <> 'Cancelada' and o.profesional = c.profesional and o.fecha = ${lit(out.fecha)}::date
      and o.hora < ${lit(out.hora)}::time + make_interval(mins => c.duracion_min)
      and ${lit(out.hora)}::time < o.hora + make_interval(mins => o.duracion_min)
  )
returning c.id, c.nombre, c.servicio_nombre, c.profesional, c.duracion_min, to_char(c.fecha, 'YYYY-MM-DD') as fecha, to_char(c.hora, 'HH24:MI') as hora;`,
};
out.sql = SQL[out.tipo] || '';
return [{ json: out }];

// Próximas horas libres (máximo 2 por día) con el horario y las citas reales de la app
const r = $input.first().json;
const e = $('Interpretar').first().json;
const cita = r.cita;
const out = { id: e.id, chatId: e.chatId, puede: Boolean(cita) && Number(cita.cambios) < 1 };
if (!out.puede) return [{ json: out }];
const h = r.horario;
const dur = Number(cita.duracion_min) || 30;
const noAtiende = new Set(r.no_atiende || []);
const periodos = [h.manana_on && [h.manana_ini, h.manana_fin], h.tarde_on && [h.tarde_ini, h.tarde_fin]].filter(Boolean);
const ocupado = new Set();
for (const c of r.citas || []) {
  if (c.id === cita.id) continue;
  const [hh, mm] = c.hora.split(':').map(Number);
  for (let t = hh * 60 + mm; t < hh * 60 + mm + c.dur; t += 30) ocupado.add(c.fecha + ' ' + t);
}
const hoy = DateTime.now().setZone('America/Bogota').startOf('day');
const libres = [];
for (let i = 1; i <= 56 && libres.length < 6; i++) {
  const dia = hoy.plus({ days: i });
  const fecha = dia.toISODate();
  // En la base los días van de 0 = lunes a 5 = sábado
  if (dia.weekday === 7 || !(h.dias || []).includes(dia.weekday - 1) || noAtiende.has(fecha)) continue;
  let delDia = 0;
  for (const [a, b] of periodos) {
    for (let t = a; t + dur <= b && delDia < 2 && libres.length < 6; t += 30) {
      let libre = true;
      for (let k = t; k < t + dur; k += 30) if (ocupado.has(fecha + ' ' + k)) libre = false;
      if (libre) { libres.push({ dia, t }); delDia++; t += 90; }
    }
  }
}
out.hay = libres.length > 0;
for (let i = 0; i < 6; i++) {
  const s = libres[i];
  if (s) {
    const hhmm = String(Math.floor(s.t / 60)).padStart(2, '0') + String(s.t % 60).padStart(2, '0');
    const hora = DateTime.fromObject({ hour: Math.floor(s.t / 60), minute: s.t % 60 }).setLocale('es').toFormat('h:mm a');
    const dia = s.dia.setLocale('es').toFormat('ccc d LLL').replace('.', '');
    out['texto' + (i + 1)] = dia.charAt(0).toUpperCase() + dia.slice(1) + ' · ' + hora;
    out['dato' + (i + 1)] = 'h|' + cita.id + '|' + s.dia.toFormat('yyyyMMdd') + '|' + hhmm;
  } else {
    out['texto' + (i + 1)] = '—';
    out['dato' + (i + 1)] = 'n|' + cita.id;
  }
}
return [{ json: out }];
